import {prepareScreamSamples} from './audio-preparation.js?v=5.5.4';
export class Sound{
 constructor(){this.volume=.6;this.context=null;this.nodes=[];this.active=false;this.screams={};this.ready=prepareScreamSamples().then(data=>{this.screamSamples=data;this.installScreams();});}
 init(){if(!this.context){try{this.context=new(window.AudioContext||window.webkitAudioContext)();this.master=this.context.createGain();this.master.gain.value=this.volume*.3;this.master.connect(this.context.destination);const buffer=this.context.createBuffer(1,this.context.sampleRate*2,this.context.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;this.noise=buffer;this.installScreams();
 const hum=this.context.createOscillator(),gain=this.context.createGain(),low=this.context.createBiquadFilter();hum.type='sawtooth';hum.frequency.value=54;low.type='lowpass';low.frequency.value=110;gain.gain.value=.13;hum.connect(low);low.connect(gain);gain.connect(this.master);hum.start();this.nodes.push(hum);this.ambient=gain;
 }catch{this.context=null;}}this.context?.resume().catch(()=>{});this.active=true;}
 installScreams(){
  if(!this.context?.createBuffer||!this.screamSamples)return;
  const {samples,sampleRate}=this.screamSamples;for(const [kind,data]of Object.entries(samples))if(!this.screams[kind]){const buffer=this.context.createBuffer(1,data.length,sampleRate);buffer.getChannelData(0).set(data);this.screams[kind]=buffer;}
 }
 impact(head=false){this.burst(head?.09:.075,head?.32:.22,head?1200:650);this.tone(head?95:72,.09,'triangle',.12,38);}
 scream(kind='birdy'){if(!this.context||!this.active||!this.screams?.[kind])return;const source=this.context.createBufferSource(),gain=this.context.createGain();source.buffer=this.screams[kind];gain.gain.value=.8;source.connect(gain);gain.connect(this.master);source.start();source.onended=()=>{source.disconnect();gain.disconnect();};}
 setVolume(v){this.volume=v;if(this.master)this.master.gain.setTargetAtTime(v*.3*(this.ducked?.42:1),this.context.currentTime,.08);}
 duck(speaking){if(this.ducked===speaking)return;this.ducked=speaking;this.setVolume(this.volume);}
 tone(freq,duration,type='sine',volume=.3,end=0){if(!this.context||!this.active)return;const t=this.context.currentTime,o=this.context.createOscillator(),g=this.context.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(end)o.frequency.exponentialRampToValueAtTime(end,t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.master);o.start();o.stop(t+duration);o.onended=()=>{o.disconnect();g.disconnect();};}
 burst(duration=.12,volume=.6,cut=1300){if(!this.context||!this.active)return;const t=this.context.currentTime,n=this.context.createBufferSource(),g=this.context.createGain(),f=this.context.createBiquadFilter();n.buffer=this.noise;f.type='lowpass';f.frequency.value=cut;g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);n.connect(f);f.connect(g);g.connect(this.master);n.start();n.stop(t+duration);n.onended=()=>{n.disconnect();f.disconnect();g.disconnect();};}
 fire(id='sidearm'){if(id==='shotgun'){this.burst(.36,1.65,2300);this.tone(86,.38,'triangle',1.0,24);}else if(id==='carbine'){this.burst(.11,1.1,4600);this.tone(150,.13,'triangle',.6,45);}else this.play('shot');}
 play(name){if(name==='shellIn'){this.burst(.07,.3,2600);this.tone(270,.05,'triangle',.1,180);}if(name==='pump'){this.burst(.19,.6,3000);this.tone(170,.13,'triangle',.18,65);}if(name==='magOut'){this.burst(.08,.35,2100);this.tone(170,.07,'triangle',.1,95);}if(name==='magIn'){this.burst(.08,.5,1800);this.tone(280,.06,'square',.1,120);}if(name==='chamber'){this.burst(.14,.5,3300);this.tone(340,.09,'triangle',.12,140);}if(name==='slam'){this.burst(.6,.9,500);this.tone(72,.7,'triangle',.5,26);}if(name==='heartbeat'){this.tone(48,.45,'sine',.5,32);this.tone(62,.25,'triangle',.2,34);}if(name==='collapse'){this.burst(2,1,430);this.tone(70,2.2,'sawtooth',.4,23);}if(name==='whisper'){this.burst(1.5,.2,2100);this.tone(110,1.8,'sine',.2,89);}if(name==='resolve'){this.tone(220,4,'sine',.3);this.tone(330,4,'sine',.2);this.tone(440,4,'sine',.1);}if(name==='shot'){this.burst(.16,1.5,3600);this.tone(120,.18,'triangle',.8,35);}if(name==='step')this.burst(.06,.08,180);if(name==='hit'){this.burst(.19,.7,650);this.tone(90,.3,'sawtooth',.3,35);}if(name==='pickup'){this.tone(440,.25,'sine',.25);this.tone(660,.5,'sine',.12);}if(name==='reload'){this.burst(.07,.4,2400);this.tone(220,.07,'square',.12);}if(name==='knife')this.burst(.16,.6,2000);if(name==='dash')this.burst(.18,.25,500);if(name==='bell'){this.tone(220,3,'sine',.4);this.tone(583,2.6,'sine',.2);this.tone(1193,1.8,'sine',.08);}if(name==='boss'){this.tone(65,1.5,'sawtooth',.5,29);this.burst(1,.5,350);}if(name==='heal')this.tone(330,.7,'sine',.3,660);if(name==='empty')this.burst(.05,.2,3500);}
 growl(pan=0,intensity=1){
  if(!this.context||!this.active)return;
  const t=this.context.currentTime,o=this.context.createOscillator(),g=this.context.createGain(),filter=this.context.createBiquadFilter(),stereo=this.context.createStereoPanner(),mod=this.context.createOscillator(),depth=this.context.createGain();
  o.type='sawtooth';o.frequency.setValueAtTime(68,t);o.frequency.exponentialRampToValueAtTime(34,t+.8);mod.frequency.value=21;depth.gain.value=11;mod.connect(depth);depth.connect(o.frequency);
  filter.type='bandpass';filter.frequency.setValueAtTime(460,t);filter.frequency.exponentialRampToValueAtTime(160,t+.85);filter.Q.value=1.8;
  stereo.pan.value=Math.max(-1,Math.min(1,pan));g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.32*intensity,t+.15);g.gain.exponentialRampToValueAtTime(.001,t+.9);
  o.connect(filter);filter.connect(g);g.connect(stereo);stereo.connect(this.master);o.start();mod.start();o.stop(t+.9);mod.stop(t+.9);
  o.onended=()=>{o.disconnect();mod.disconnect();depth.disconnect();filter.disconnect();g.disconnect();stereo.disconnect();};
 }
 pause(p){this.active=!p;if(!p&&this.context?.state==='suspended')this.context.resume().catch(()=>{});if(this.ambient)this.ambient.gain.setTargetAtTime(p?.02:.13,this.context.currentTime,.5);}
}
